        System.out.println(b.getJudul() + " " + b.getTenggat().getDayOfWeek());

        t.setDibuat(LocalDateTime.of(2026, 11, 11, 9, 30));
        System.out.println(mapper.writeValueAsString(t));

        long sisa = ChronoUnit.DAYS.between(LocalDate.of(2026, 11, 11), t.getTenggat());
        System.out.println("Sisa " + sisa + " hari");
    }
}

